import sys

def main():
    data = sys.stdin.read().split()
    q = int(data[0])
    p = 1
    root = {}
    out = []
    for _ in range(q):
        op = data[p]
        path = data[p + 1]
        names = path.split('/')[1:] if path != '/' else []
        if op == 'ls':
            p += 2
            node = root
            for nm in names:
                node = node[nm]
            if isinstance(node, list):
                out.append(names[-1])
            else:
                keys = sorted(node)
                out.append(' '.join(keys) if keys else 'EMPTY')
        elif op == 'mkdir':
            p += 2
            node = root
            for nm in names:
                node = node.setdefault(nm, {})
        elif op == 'addContentToFile':
            content = data[p + 2]
            p += 3
            node = root
            for nm in names[:-1]:
                node = node.setdefault(nm, {})
            node.setdefault(names[-1], []).append(content)
        else:
            p += 2
            node = root
            for nm in names:
                node = node[nm]
            out.append(''.join(node))
    print('\n'.join(out))

main()

