import sys

def parent(path):
    i = path.rfind('/')
    return '/' if i == 0 else path[:i]

data = sys.stdin.read().split()
q = int(data[0])
p = 1
dirs = {'/'}
files = {}
out = []

def add_dirs(path):
    cur = path
    while cur != '/':
        dirs.add(cur)
        cur = parent(cur)

for _ in range(q):
    op = data[p]
    path = data[p + 1]
    if op == 'ls':
        p += 2
        if path in files:
            out.append(path.split('/')[-1])
        else:
            names = []
            for d in dirs:
                if d != '/' and parent(d) == path:
                    names.append(d.split('/')[-1])
            for f in files:
                if parent(f) == path:
                    names.append(f.split('/')[-1])
            names.sort()
            out.append(' '.join(names) if names else 'EMPTY')
    elif op == 'mkdir':
        p += 2
        add_dirs(path)
    elif op == 'addContentToFile':
        c = data[p + 2]
        p += 3
        add_dirs(parent(path))
        files[path] = files.get(path, '') + c
    else:
        p += 2
        out.append(files[path])
print('\n'.join(out))

